    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate, string Status)> OnTaskCreate { get; set; }

    private bool showForm;

    private async Task HandleMoveLeft(int taskId)
    {
        await OnMove.InvokeAsync((taskId, "left"));
    }

    private async Task HandleMoveRight(int taskId)
    {
        await OnMove.InvokeAsync((taskId, "right"));
    }

